  nextCtx.fillStyle = '#000';
  nextCtx.fillRect(0, 0, nextCanvas.width, nextCanvas.height);
  if (!next) return;
  const offsetX = (4 - next.shape[0].length) / 2;
  const offsetY = (4 - next.shape.length) / 2;
  for (let y = 0; y < next.shape.length; y++) {
    for (let x = 0; x < next.shape[y].length; x++) {
      if (next.shape[y][x]) {
        drawBlock(offsetX + x, offsetY + y, next.color, nextCtx, size);
      }
    }
  }
}

function drawGameOver() {
  ctx.fillStyle = 'rgba(0,0,0,0.7)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 36px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2 - 20);
  ctx.font = '18px sans-serif';
  ctx.fillText('Click New Game to restart', canvas.width / 2, canvas.height / 2 + 20);
}

function drawPause() {
  ctx.fillStyle = 'rgba(0,0,0,0.7)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 36px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('PAUSED', canvas.width / 2, canvas.height / 2);
}

