  lines = 0;
  level = 1;
  dropInterval = 1000;
  dropCounter = 0;
  gameOver = false;
  paused = false;
  current = null;
  next = null;
  updateUI();
  spawnPiece();
  update();
}

document.addEventListener('keydown', e => {
  if (gameOver) return;

  if (e.key === 'p' || e.key === 'P') {
    paused = !paused;
    if (!paused) {
      lastTime = performance.now();
      dropCounter = 0;
    }
    return;
  }

  if (paused || !current) return;

  switch (e.key) {
    case 'ArrowLeft':
      if (isValidPosition(current, -1, 0)) current.x--;
      break;
    case 'ArrowRight':
      if (isValidPosition(current, 1, 0)) current.x++;
      break;
    case 'ArrowDown':
      if (isValidPosition(current, 0, 1)) {
        current.y++;
        score += 1;
        dropCounter = 0;
        updateUI();
      }
      break;
    case 'ArrowUp': {
      const rotated = rotate(current.shape);
      let kick = 0;
      if (!isValidPosition(current, 0, 0, rotated)) {
        kick = isValidPosition(current, 1, 0, rotated) ? 1 : isValidPosition(current, -1, 0, rotated) ? -1 : 0;
      }
      if (kick !== undefined) {
        current.shape = rotated;
        current.x += kick;
      }
      break;
    }
    case ' ':
      e.preventDefault();
      hardDrop();
      break;
  }
});

document.getElementById('new-game').addEventListener('click', newGame);

newGame();
