  context.strokeRect(x * size, y * size, size, size);
  context.fillStyle = 'rgba(255,255,255,0.15)';
  context.fillRect(x * size, y * size, size * 0.3, size * 0.3);
}

function drawGhost() {
  if (!current) return;
