<body>

<div id="overlay">
  <h1>AMBIENT CANVAS</h1>
  <p>Place sound objects on the canvas to weave generative ambient textures. Each object is a living loop — move them, layer them, create your own soundscape.</p>
  <button id="start-btn">Enter</button>
</div>

<div id="topbar">
  <h2>AMBIENT CANVAS</h2>
  <button id="clear-btn">Clear All</button>
</div>

<div id="info">
  Click to place &middot; Drag to move<br>
  Right-click to remove
</div>

<canvas id="canvas"></canvas>

<div id="toolbar">
  <div class="tool active" data-type="drone" title="Warm drone">
    <span>🌊</span>
    <span class="tooltip">Warm Drone</span>
  </div>
  <div class="tool" data-type="bell" title="Crystal bell">
    <span>🔔</span>
    <span class="tooltip">Crystal Bell</span>
  </div>
  <div class="tool" data-type="pad" title="Soft pad">
    <span>☁️</span>
    <span class="tooltip">Soft Pad</span>
  </div>
  <div class="tool" data-type="texture" title="Noise texture">
    <span>✨</span>
    <span class="tooltip">Noise Texture</span>
  </div>
  <div class="tool" data-type="pulse" title="Slow pulse">
    <span>💓</span>
    <span class="tooltip">Slow Pulse</span>
  </div>
  <div class="divider"></div>
  <div class="tool" id="mute-btn" title="Mute/unmute">
    <span>🔊</span>
    <span class="tooltip">Mute All</span>
  </div>
</div>

<script>
/* ============================================================
   Ambient Canvas — Generative Sound Toy
   ============================================================ */

const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

let W, H;
function resize() {
  W = canvas.width = window.innerWidth;
  H = canvas.height = window.innerHeight;
}
window.addEventListener('resize', resize);
resize();

/* ---------- Audio Engine ---------- */
let audioCtx = null;
let masterGain = null;
let isMuted = false;

function initAudio() {
  if (audioCtx) return;
  audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  masterGain = audioCtx.createGain();
  masterGain.gain.value = 0.5;
  masterGain.connect(audioCtx.destination);
}

function resumeAudio() {
  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
}

/* ---------- Sound Generators ---------- */

function mtof(m) { return 440 * Math.pow(2, (m - 69) / 12); }

const SCALES = {
  pentatonic: [0, 2, 4, 7, 9],
  minor: [0, 2, 3, 5, 7, 8, 10],
  major: [0, 2, 4, 5, 7, 9, 11],
  whole: [0, 2, 4, 6, 8, 10],
};

function pickNote(scaleName, baseOctave) {
  const scale = SCALES[scaleName];
  const degree = scale[Math.floor(Math.random() * scale.length)];
  const octave = baseOctave + Math.floor(Math.random() * 3);
  return 36 + degree + octave * 12;
}

function makeDrone(x, y) {
  const root = 36 + Math.floor((x / W) * 12);
  const freq = mtof(root);
  const detuneAmt = 3 + Math.random() * 5;

  const osc1 = audioCtx.createOscillator();
  const osc2 = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  const filter = audioCtx.createBiquadFilter();
  const lfo = audioCtx.createOscillator();
  const lfoGain = audioCtx.createGain();

  osc1.type = 'sine';
  osc2.type = 'sine';
  osc1.frequency.value = freq;
  osc2.frequency.value = freq * 1.5;
  osc2.detune.value = detuneAmt;

  filter.type = 'lowpass';
  filter.frequency.value = 400 + (y / H) * 800;
  filter.Q.value = 2;

  lfo.frequency.value = 0.1 + Math.random() * 0.3;
  lfoGain.gain.value = 150;

  gain.gain.value = 0;
  gain.gain.linearRampToValueAtTime(0.08, audioCtx.currentTime + 2);

  lfo.connect(lfoGain);
  lfoGain.connect(filter.frequency);
  osc1.connect(filter);
  osc2.connect(filter);
  filter.connect(gain);
  gain.connect(masterGain);

  osc1.start();
  osc2.start();
  lfo.start();

  return {
    nodes: [osc1, osc2, lfo],
    gain,
    params: { freq, type: 'drone' },
    dispose() {
      gain.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 0.5);
      setTimeout(() => {
        osc1.stop(); osc2.stop(); lfo.stop();
        [osc1, osc2, lfo, gain, filter, lfoGain].forEach(n => n.disconnect());
      }, 600);
    }
  };
}

function makeBell(x, y) {
  const note = pickNote('pentatonic', 3 + Math.floor((1 - y / H) * 2));
  const baseFreq = mtof(note);
  const interval = 3 + Math.random() * 5;

  const voices = [];
  const master = audioCtx.createGain();
  master.gain.value = 0.12;

  for (let i = 0; i < 3; i++) {
    const car = audioCtx.createOscillator();
    const mod = audioCtx.createOscillator();
    const modGain = audioCtx.createGain();
    const vGain = audioCtx.createGain();

    const ratio = [2, 3.5, 5][i];
    car.type = 'sine';
    mod.type = 'sine';
    car.frequency.value = baseFreq * (1 + i * 0.005);
    mod.frequency.value = baseFreq * ratio;
    modGain.gain.value = baseFreq * ratio * (1.5 + Math.random());
    vGain.gain.value = [0.5, 0.3, 0.2][i];

    mod.connect(modGain);
    modGain.connect(car.frequency);
    car.connect(vGain);
    vGain.connect(master);
    car.start();
    mod.start();
    voices.push(car, mod);
  }

  // Periodic envelope retrigger
  const envLoop = setInterval(() => {
    if (!audioCtx) { clearInterval(envLoop); return; }
    master.gain.cancelScheduledValues(audioCtx.currentTime);
    master.gain.setValueAtTime(0, audioCtx.currentTime);
    master.gain.exponentialRampToValueAtTime(0.12, audioCtx.currentTime + 0.05);
    master.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + interval);
  }, interval * 1000);

  // First trigger
  master.gain.setValueAtTime(0, audioCtx.currentTime);
  master.gain.exponentialRampToValueAtTime(0.12, audioCtx.currentTime + 0.05);
  master.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + interval);

  master.connect(masterGain);

  return {
    nodes: voices,
    gain: master,
    params: { baseFreq, type: 'bell' },
    dispose() {
      clearInterval(envLoop);
      master.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 0.3);
      setTimeout(() => voices.forEach(v => v.stop()), 400);
    }
  };
}

function makePad(x, y) {
  const note = pickNote('minor', 2 + Math.floor((1 - y / H) * 2));
  const freq = mtof(note);

  const osc1 = audioCtx.createOscillator();
  const osc2 = audioCtx.createOscillator();
  const osc3 = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  const filter = audioCtx.createBiquadFilter();
  const filterLfo = audioCtx.createOscillator();
  const filterLfoGain = audioCtx.createGain();

  osc1.type = 'triangle';
  osc2.type = 'sine';
  osc3.type = 'sine';
  osc1.frequency.value = freq;
  osc2.frequency.value = freq * 1.01;
  osc3.frequency.value = freq * 0.99;

  filter.type = 'lowpass';
  filter.frequency.value = 600;
  filter.Q.value = 1;

  filterLfo.frequency.value = 0.05 + Math.random() * 0.1;
  filterLfoGain.gain.value = 400 + (y / H) * 600;

  gain.gain.value = 0;
  gain.gain.linearRampToValueAtTime(0.06, audioCtx.currentTime + 3);

  filterLfo.connect(filterLfoGain);
  filterLfoGain.connect(filter.frequency);
  osc1.connect(filter);
  osc2.connect(filter);
  osc3.connect(filter);
  filter.connect(gain);
  gain.connect(masterGain);

  osc1.start(); osc2.start(); osc3.start(); filterLfo.start();

  return {
    nodes: [osc1, osc2, osc3, filterLfo],
    gain,
    params: { freq, type: 'pad' },
    dispose() {
      gain.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 1);
      setTimeout(() => {
        [osc1, osc2, osc3, filterLfo].forEach(o => o.stop());
      }, 1200);
    }
  };
}

function makeTexture(x, y) {
  const bufferSize = audioCtx.sampleRate * 2;
  const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) {
    data[i] = (Math.random() * 2 - 1) * 0.5 + (Math.random() * 2 - 1) * 0.3;
  }

  const source = audioCtx.createBufferSource();
  source.buffer = buffer;
  source.loop = true;

  const filter = audioCtx.createBiquadFilter();
  filter.type = 'bandpass';
  filter.frequency.value = 200 + (1 - y / H) * 2000;
  filter.Q.value = 1 + Math.random() * 3;

  const gain = audioCtx.createGain();
  gain.gain.value = 0;
  gain.gain.linearRampToValueAtTime(0.04, audioCtx.currentTime + 2);

  const mod = audioCtx.createOscillator();
  const modGain = audioCtx.createGain();
  mod.frequency.value = 0.2 + Math.random() * 0.5;
  modGain.gain.value = 0.02;

  mod.connect(modGain);
  modGain.connect(gain.gain);
  source.connect(filter);
  filter.connect(gain);
  gain.connect(masterGain);

  source.start();
  mod.start();

  return {
    nodes: [source, mod],
    gain,
    params: { type: 'texture' },
    dispose() {
      gain.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 0.5);
      setTimeout(() => { source.stop(); mod.stop(); }, 600);
    }
  };
}

function makePulse(x, y) {
  const note = pickNote('whole', 1);
  const freq = mtof(note) * 0.5;
  const rate = 0.2 + Math.random() * 0.4;

  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  const filter = audioCtx.createBiquadFilter();

  osc.type = 'sine';
  osc.frequency.value = freq;

  filter.type = 'lowpass';
  filter.frequency.value = 300 + (y / H) * 500;
  filter.Q.value = 4;

  gain.gain.value = 0;

  osc.connect(filter);
  filter.connect(gain);
  gain.connect(masterGain);
  osc.start();

  const loop = setInterval(() => {
    if (!audioCtx) { clearInterval(loop); return; }
    const t = audioCtx.currentTime;
    gain.gain.cancelScheduledValues(t);
    gain.gain.setValueAtTime(0, t);
    gain.gain.linearRampToValueAtTime(0.1, t + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
  }, (1 / rate) * 1000);

  // First pulse
  gain.gain.setValueAtTime(0, audioCtx.currentTime);
  gain.gain.linearRampToValueAtTime(0.1, audioCtx.currentTime + 0.02);
  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.5);

  return {
    nodes: [osc],
    gain,
    params: { freq, type: 'pulse' },
    dispose() {
      clearInterval(loop);
      gain.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 0.3);
      setTimeout(() => osc.stop(), 400);
    }
  };
}

const MAKERS = {
  drone: makeDrone,
  bell: makeBell,
  pad: makePad,
  texture: makeTexture,
  pulse: makePulse,
};

const COLORS = {
  drone: { r: 120, g: 160, b: 255 },
  bell: { r: 180, g: 240, b: 220 },
  pad: { r: 200, g: 140, b: 240 },
  texture: { r: 255, g: 200, b: 120 },
  pulse: { r: 255, g: 120, b: 140 },
};

/* ---------- Objects ---------- */

let objects = [];
let nextId = 1;

function addObject(type, x, y) {
  if (!audioCtx) return;
  const sound = MAKERS[type](x, y);
  objects.push({ id: nextId++, type, x, y, r: 0, targetR: 18 + Math.random() * 8, sound, birth: performance.now(), phase: Math.random() * Math.PI * 2 });
}

function removeObject(id) {
  const idx = objects.findIndex(o => o.id === id);
  if (idx >= 0) {
    objects[idx].sound.dispose();
    objects.splice(idx, 1);
  }
}

function clearAll() {
  objects.forEach(o => o.sound.dispose());
  objects = [];
}

/* ---------- Interaction ---------- */

let activeType = 'drone';
let dragging = null;
let dragOffX = 0, dragOffY = 0;

// Tool selection
const tools = document.querySelectorAll('.tool[data-type]');
tools.forEach(t => {
  t.addEventListener('click', () => {
    tools.forEach(x => x.classList.remove('active'));
    t.classList.add('active');
    activeType = t.dataset.type;
  });
});

// Mute
const muteBtn = document.getElementById('mute-btn');
muteBtn.addEventListener('click', () => {
  isMuted = !isMuted;
  if (masterGain) masterGain.gain.linearRampToValueAtTime(isMuted ? 0 : 0.5, audioCtx.currentTime + 0.1);
  muteBtn.querySelector('span').textContent = isMuted ? '🔇' : '🔊';
  muteBtn.querySelector('.tooltip').textContent = isMuted ? 'Unmute' : 'Mute All';
});

// Clear
const clearBtn = document.getElementById('clear-btn');
clearBtn.addEventListener('click', clearAll);

// Canvas events
function getPos(e) {
  const rect = canvas.getBoundingClientRect();
  const cx = e.clientX || (e.touches && e.touches[0].clientX);
  const cy = e.clientY || (e.touches && e.touches[0].clientY);
  return { x: cx - rect.left, y: cy - rect.top };
}

function findObject(x, y) {
  for (let i = objects.length - 1; i >= 0; i--) {
    const o = objects[i];
    const dx = o.x - x, dy = o.y - y;
    if (dx * dx + dy * dy < (o.r + 10) ** 2) return o;
  }
  return null;
}

canvas.addEventListener('mousedown', e => {
  if (!audioCtx) return;
  resumeAudio();
  const p = getPos(e);
  if (e.button === 2) {
    const o = findObject(p.x, p.y);
    if (o) removeObject(o.id);
    return;
  }
  const o = findObject(p.x, p.y);
  if (o) {
    dragging = o;
    dragOffX = p.x - o.x;
    dragOffY = p.y - o.y;
  } else {
    addObject(activeType, p.x, p.y);
  }
});

canvas.addEventListener('mousemove', e => {
  if (!dragging) return;
  const p = getPos(e);
  dragging.x = p.x - dragOffX;
  dragging.y = p.y - dragOffY;
});

canvas.addEventListener('mouseup', () => { dragging = null; });
canvas.addEventListener('mouseleave', () => { dragging = null; });
canvas.addEventListener('contextmenu', e => e.preventDefault());

// Touch support
canvas.addEventListener('touchstart', e => {
  if (!audioCtx) return;
  resumeAudio();
  e.preventDefault();
  const p = getPos(e);
  const o = findObject(p.x, p.y);
  if (o) {
    dragging = o;
    dragOffX = p.x - o.x;
    dragOffY = p.y - o.y;
  } else {
    addObject(activeType, p.x, p.y);
  }
}, { passive: false });

canvas.addEventListener('touchmove', e => {
  e.preventDefault();
  if (!dragging) return;
  const p = getPos(e);
  dragging.x = p.x - dragOffX;
  dragging.y = p.y - dragOffY;
}, { passive: false });

canvas.addEventListener('touchend', () => { dragging = null; });

/* ---------- Rendering ---------- */

const bgStars = [];
for (let i = 0; i < 80; i++) {
  bgStars.push({
    x: Math.random(), y: Math.random(),
    r: 0.3 + Math.random() * 1.2,
    speed: 0.02 + Math.random() * 0.05,
    phase: Math.random() * Math.PI * 2
  });
}

function draw() {
  const now = performance.now();

  // Fade background
  ctx.fillStyle = 'rgba(10, 10, 15, 0.35)';
  ctx.fillRect(0, 0, W, H);

  // Stars
  for (const s of bgStars) {
    const alpha = 0.15 + 0.15 * Math.sin(now * 0.001 * s.speed + s.phase);
    ctx.fillStyle = `rgba(200, 210, 255, ${alpha})`;
    ctx.beginPath();
    ctx.arc(s.x * W, s.y * H, s.r, 0, Math.PI * 2);
    ctx.fill();
  }

  // Objects
  for (const o of objects) {
    const col = COLORS[o.type];
    const age = Math.min((now - o.birth) / 600, 1);
    o.r += (o.targetR - o.r) * 0.08;

    const breathe = 1 + 0.08 * Math.sin(now * 0.002 + o.phase);
    const radius = o.r * breathe * (0.5 + 0.5 * age);

    // Outer glow
    const grad = ctx.createRadialGradient(o.x, o.y, radius * 0.3, o.x, o.y, radius * 4);
    grad.addColorStop(0, `rgba(${col.r}, ${col.g}, ${col.b}, ${0.25 * age})`);
    grad.addColorStop(0.5, `rgba(${col.r}, ${col.g}, ${col.b}, ${0.06 * age})`);
    grad.addColorStop(1, `rgba(${col.r}, ${col.g}, ${col.b}, 0)`);
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(o.x, o.y, radius * 4, 0, Math.PI * 2);
    ctx.fill();

    // Core
    ctx.fillStyle = `rgba(${col.r}, ${col.g}, ${col.b}, ${0.85 * age})`;
    ctx.beginPath();
    ctx.arc(o.x, o.y, radius, 0, Math.PI * 2);
    ctx.fill();

    // Ring
    ctx.strokeStyle = `rgba(${col.r}, ${col.g}, ${col.b}, ${0.3 * age})`;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(o.x, o.y, radius * 1.6 + 2 * Math.sin(now * 0.003 + o.phase), 0, Math.PI * 2);
    ctx.stroke();

    // Visual pulse for bell/pulse types
    if (o.type === 'bell' || o.type === 'pulse') {
      const pulseAlpha = 0.15 * (0.5 + 0.5 * Math.sin(now * 0.004 + o.phase));
      ctx.strokeStyle = `rgba(${col.r}, ${col.g}, ${col.b}, ${pulseAlpha})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(o.x, o.y, radius * (2.5 + 0.5 * Math.sin(now * 0.003)), 0, Math.PI * 2);
      ctx.stroke();
    }
  }

  // Subtle vignette
  const vig = ctx.createRadialGradient(W/2, H/2, Math.min(W,H)*0.3, W/2, H/2, Math.min(W,H)*0.9);
  vig.addColorStop(0, 'rgba(0,0,0,0)');
  vig.addColorStop(1, 'rgba(0,0,0,0.5)');
  ctx.fillStyle = vig;
  ctx.fillRect(0, 0, W, H);

  requestAnimationFrame(draw);
}

/* ---------- Start Overlay ---------- */

const overlay = document.getElementById('overlay');
const startBtn = document.getElementById('start-btn');

startBtn.addEventListener('click', () => {
  initAudio();
  overlay.classList.add('hidden');
  draw();
});
</script>
</body>
</html>
