    transform: translateX(-50%) translateY(0);
  }

  .divider {
    width: 1px;
    background: rgba(255,255,255,0.1);
    margin: 4px 6px;
  }

  #overlay {
    position: fixed;
    inset: 0;
    background: rgba(10, 10, 15, 0.96);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
