    transition: opacity 0.6s ease;
  }

  #overlay.hidden { opacity: 0; pointer-events: none; }

  #overlay h1 {
    font-size: 2.4rem;
    font-weight: 300;
    letter-spacing: 0.1em;
    margin-bottom: 12px;
    background: linear-gradient(135deg, #c9b8ff, #8ec5fc);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  #overlay p {
    color: #888;
    font-size: 1rem;
    margin-bottom: 32px;
    max-width: 400px;
    text-align: center;
    line-height: 1.6;
  }

  #start-btn {
    padding: 14px 36px;
    border-radius: 30px;
    border: 1px solid rgba(255,255,255,0.2);
    background: rgba(255,255,255,0.08);
