  }

  .tool:hover { background: rgba(255,255,255,0.12); transform: translateY(-2px); }
  .tool.active {
    border-color: rgba(255,255,255,0.35);
    background: rgba(255,255,255,0.14);
  }

  .tool .tooltip {
    position: absolute;
    bottom: 110%;
    left: 50%;
    transform: translateX(-50%) translateY(4px);
    background: rgba(0,0,0,0.9);
    padding: 6px 10px;
