<script>
/* ============================================================
   Ambient Canvas — Generative Sound Toy v2
   ============================================================ */

const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
const hoverLabel = document.getElementById('hover-label');
const objCount = document.getElementById('obj-count');

let W, H;
function resize() {
  W = canvas.width = window.innerWidth;
  H = canvas.height = window.innerHeight;
}
window.addEventListener('resize', resize);
resize();

/* ---------- Audio Engine ---------- */
let audioCtx = null;
let masterGain = null;
let isMuted = false;

function initAudio() {
  if (audioCtx) return;
  audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  masterGain = audioCtx.createGain();
  masterGain.gain.value = 0.5;
  masterGain.connect(audioCtx.destination);
}

function resumeAudio() {
  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
}

/* ---------- Sound Generators ---------- */

function mtof(m) { return 440 * Math.pow(2, (m - 69) / 12); }

const SCALES = {
  pentatonic: [0, 2, 4, 7, 9],
  minor: [0, 2, 3, 5, 7, 8, 10],
  major: [0, 2, 4, 5, 7, 9, 11],
  whole: [0, 2, 4, 6, 8, 10],
};

function pickNote(scaleName, baseOctave) {
  const scale = SCALES[scaleName];
  const degree = scale[Math.floor(Math.random() * scale.length)];
  const octave = baseOctave + Math.floor(Math.random() * 3);
  return 36 + degree + octave * 12;
}

function makeAnalyser() {
  const analyser = audioCtx.createAnalyser();
  analyser.fftSize = 256;
  analyser.smoothingTimeConstant = 0.7;
  return analyser;
}

function makeDrone(x, y) {
  const root = 36 + Math.floor((x / W) * 12);
  const freq = mtof(root);
  const detuneAmt = 3 + Math.random() * 5;

  const analyser = makeAnalyser();

  const osc1 = audioCtx.createOscillator();
  const osc2 = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  const filter = audioCtx.createBiquadFilter();
  const lfo = audioCtx.createOscillator();
  const lfoGain = audioCtx.createGain();

  osc1.type = 'sine';
  osc2.type = 'sine';
  osc1.frequency.value = freq;
  osc2.frequency.value = freq * 1.5;
  osc2.detune.value = detuneAmt;

  filter.type = 'lowpass';
  filter.frequency.value = 400 + (y / H) * 1200;
  filter.Q.value = 2;

  lfo.frequency.value = 0.1 + Math.random() * 0.3;
  lfoGain.gain.value = 200;

  gain.gain.value = 0;
  gain.gain.linearRampToValueAtTime(0.06, audioCtx.currentTime + 2);

  lfo.connect(lfoGain);
  lfoGain.connect(filter.frequency);
  osc1.connect(filter);
  osc2.connect(filter);
  filter.connect(gain);
  gain.connect(analyser);
  analyser.connect(masterGain);

  osc1.start();
  osc2.start();
  lfo.start();

  return {
    nodes: [osc1, osc2, lfo],
    gain,
    analyser,
    dataArray: new Uint8Array(analyser.frequencyBinCount),
    params: { freq, type: 'drone' },
    dispose() {
      gain.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 0.5);
      setTimeout(() => {
        osc1.stop(); osc2.stop(); lfo.stop();
        [osc1, osc2, lfo, gain, filter, lfoGain, analyser].forEach(n => n.disconnect());
      }, 600);
    }
  };
}

function makeBell(x, y) {
  const note = pickNote('pentatonic', 3 + Math.floor((1 - y / H) * 2));
  const baseFreq = mtof(note);
  const interval = 3 + Math.random() * 5;

  const analyser = makeAnalyser();
  const voices = [];
  const master = audioCtx.createGain();
  master.gain.value = 0.08;

  for (let i = 0; i < 3; i++) {
    const car = audioCtx.createOscillator();
    const mod = audioCtx.createOscillator();
    const modGain = audioCtx.createGain();
    const vGain = audioCtx.createGain();

    const ratio = [2, 3.5, 5][i];
    car.type = 'sine';
    mod.type = 'sine';
    car.frequency.value = baseFreq * (1 + i * 0.005);
    mod.frequency.value = baseFreq * ratio;
    modGain.gain.value = baseFreq * ratio * (1.5 + Math.random());
    vGain.gain.value = [0.5, 0.3, 0.2][i];

    mod.connect(modGain);
    modGain.connect(car.frequency);
    car.connect(vGain);
    vGain.connect(master);
    car.start();
    mod.start();
    voices.push(car, mod);
  }

  const envLoop = setInterval(() => {
    if (!audioCtx) { clearInterval(envLoop); return; }
    master.gain.cancelScheduledValues(audioCtx.currentTime);
    master.gain.setValueAtTime(0, audioCtx.currentTime);
    master.gain.exponentialRampToValueAtTime(0.08, audioCtx.currentTime + 0.05);
    master.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + interval);
  }, interval * 1000);

  master.gain.setValueAtTime(0, audioCtx.currentTime);
  master.gain.exponentialRampToValueAtTime(0.08, audioCtx.currentTime + 0.05);
  master.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + interval);

  master.connect(analyser);
  analyser.connect(masterGain);

  return {
    nodes: voices,
    gain: master,
    analyser,
    dataArray: new Uint8Array(analyser.frequencyBinCount),
    params: { baseFreq, type: 'bell' },
    dispose() {
      clearInterval(envLoop);
      master.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 0.3);
      setTimeout(() => voices.forEach(v => v.stop()), 400);
    }
  };
}

function makePad(x, y) {
  const note = pickNote('minor', 2 + Math.floor((1 - y / H) * 2));
  const freq = mtof(note);

  const analyser = makeAnalyser();
  const osc1 = audioCtx.createOscillator();
  const osc2 = audioCtx.createOscillator();
  const osc3 = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  const filter = audioCtx.createBiquadFilter();
  const filterLfo = audioCtx.createOscillator();
  const filterLfoGain = audioCtx.createGain();

  osc1.type = 'triangle';
  osc2.type = 'sine';
  osc3.type = 'sine';
  osc1.frequency.value = freq;
  osc2.frequency.value = freq * 1.01;
  osc3.frequency.value = freq * 0.99;

  filter.type = 'lowpass';
  filter.frequency.value = 600;
  filter.Q.value = 1;

  filterLfo.frequency.value = 0.05 + Math.random() * 0.1;
  filterLfoGain.gain.value = 500 + (y / H) * 800;

  gain.gain.value = 0;
  gain.gain.linearRampToValueAtTime(0.05, audioCtx.currentTime + 3);

  filterLfo.connect(filterLfoGain);
  filterLfoGain.connect(filter.frequency);
  osc1.connect(filter);
  osc2.connect(filter);
  osc3.connect(filter);
  filter.connect(gain);
  gain.connect(analyser);
  analyser.connect(masterGain);

  osc1.start(); osc2.start(); osc3.start(); filterLfo.start();

  return {
    nodes: [osc1, osc2, osc3, filterLfo],
    gain,
    analyser,
    dataArray: new Uint8Array(analyser.frequencyBinCount),
    params: { freq, type: 'pad' },
    dispose() {
      gain.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 1);
      setTimeout(() => {
        [osc1, osc2, osc3, filterLfo].forEach(o => o.stop());
      }, 1200);
    }
  };
}

function makeTexture(x, y) {
  const bufferSize = audioCtx.sampleRate * 2;
  const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) {
    data[i] = (Math.random() * 2 - 1) * 0.5 + (Math.random() * 2 - 1) * 0.3;
  }

  const analyser = makeAnalyser();
  const source = audioCtx.createBufferSource();
  source.buffer = buffer;
  source.loop = true;

  const filter = audioCtx.createBiquadFilter();
  filter.type = 'bandpass';
  filter.frequency.value = 200 + (1 - y / H) * 2000;
  filter.Q.value = 1 + Math.random() * 3;

  const gain = audioCtx.createGain();
  gain.gain.value = 0;
  gain.gain.linearRampToValueAtTime(0.04, audioCtx.currentTime + 2);

  const mod = audioCtx.createOscillator();
  const modGain = audioCtx.createGain();
  mod.frequency.value = 0.2 + Math.random() * 0.5;
  modGain.gain.value = 0.02;

  mod.connect(modGain);
  modGain.connect(gain.gain);
  source.connect(filter);
  filter.connect(gain);
  gain.connect(analyser);
  analyser.connect(masterGain);

  source.start();
  mod.start();

  return {
    nodes: [source, mod],
    gain,
    analyser,
    dataArray: new Uint8Array(analyser.frequencyBinCount),
    params: { type: 'texture' },
    dispose() {
      gain.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 0.5);
      setTimeout(() => { source.stop(); mod.stop(); }, 600);
    }
  };
}

function makePulse(x, y) {
  const note = pickNote('whole', 1);
  const freq = mtof(note) * 0.5;
  const rate = 0.2 + Math.random() * 0.4;

  const analyser = makeAnalyser();
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  const filter = audioCtx.createBiquadFilter();

  osc.type = 'sine';
  osc.frequency.value = freq;

  filter.type = 'lowpass';
  filter.frequency.value = 300 + (y / H) * 500;
  filter.Q.value = 4;

  gain.gain.value = 0;

  osc.connect(filter);
  filter.connect(gain);
  gain.connect(analyser);
  analyser.connect(masterGain);
  osc.start();

  const loop = setInterval(() => {
    if (!audioCtx) { clearInterval(loop); return; }
    const t = audioCtx.currentTime;
    gain.gain.cancelScheduledValues(t);
    gain.gain.setValueAtTime(0, t);
    gain.gain.linearRampToValueAtTime(0.08, t + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
  }, (1 / rate) * 1000);

  gain.gain.setValueAtTime(0, audioCtx.currentTime);
  gain.gain.linearRampToValueAtTime(0.08, audioCtx.currentTime + 0.02);
  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.5);

  return {
    nodes: [osc],
    gain,
    analyser,
    dataArray: new Uint8Array(analyser.frequencyBinCount),
    params: { freq, type: 'pulse' },
    dispose() {
      clearInterval(loop);
      gain.gain.linearRampToValueAtTime(0, audioCtx.currentTime + 0.3);
      setTimeout(() => osc.stop(), 400);
    }
  };
}

const MAKERS = {
  drone: makeDrone,
  bell: makeBell,
  pad: makePad,
  texture: makeTexture,
  pulse: makePulse,
};

const TYPE_INFO = {
  drone: { label: 'Warm Drone', note: 'sustained, slowly evolving' },
  bell: { label: 'Crystal Bell', note: 'FM tones, rhythmic' },
  pad: { label: 'Soft Pad', note: 'breathing, harmonic' },
  texture: { label: 'Noise Texture', note: 'granular, atmospheric' },
  pulse: { label: 'Slow Pulse', note: 'heartbeat, deep' },
};

const COLORS = {
  drone:  { r: 120, g: 160, b: 255, glow: 'rgba(120,160,255,0.15)' },
  bell:   { r: 180, g: 240, b: 220, glow: 'rgba(180,240,220,0.12)' },
  pad:    { r: 200, g: 140, b: 240, glow: 'rgba(200,140,240,0.12)' },
  texture:{ r: 255, g: 200, b: 120, glow: 'rgba(255,200,120,0.12)' },
  pulse:  { r: 255, g: 120, b: 140, glow: 'rgba(255,120,140,0.12)' },
};

/* ---------- Objects & Particles ---------- */

let objects = [];
let particles = [];
let nextId = 1;

function updateCount() {
  const n = objects.length;
  objCount.textContent = n === 0 ? '0 objects' : `${n} object${n !== 1 ? 's' : ''}`;
  objCount.classList.toggle('has-objects', n > 0);
}

function spawnParticles(x, y, color, count = 12) {
  for (let i = 0; i < count; i++) {
    const angle = (Math.PI * 2 / count) * i + Math.random() * 0.5;
    const speed = 1.5 + Math.random() * 3;
    particles.push({
      x, y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      life: 1,
      decay: 0.015 + Math.random() * 0.02,
      r: 1.5 + Math.random() * 2.5,
      color,
      birth: performance.now(),
    });
  }
}

function addObject(type, x, y) {
  if (!audioCtx) return;
  const sound = MAKERS[type](x, y);
  const obj = {
    id: nextId++, type, x, y,
    r: 0, targetR: 16 + Math.random() * 8,
    sound, birth: performance.now(),
    phase: Math.random() * Math.PI * 2,
    hover: 0,
    grabbed: false,
    removalTime: null,
  };
  objects.push(obj);
  spawnParticles(x, y, COLORS[type], 14);
  updateCount();
}

function removeObject(id, withFx = true) {
  const idx = objects.findIndex(o => o.id === id);
  if (idx >= 0) {
    const o = objects[idx];
    if (withFx) spawnParticles(o.x, o.y, COLORS[o.type], 18);
    o.sound.dispose();
    objects.splice(idx, 1);
    updateCount();
  }
}

function clearAll() {
  objects.forEach(o => {
    spawnParticles(o.x, o.y, COLORS[o.type], 10);
    o.sound.dispose();
  });
  objects = [];
  updateCount();
}

/* ---------- Interaction ---------- */

let activeType = 'drone';
let dragging = null;
let dragOffX = 0, dragOffY = 0;
let hoveredObject = null;
let mouseX = W / 2, mouseY = H / 2;

const tools = document.querySelectorAll('.tool[data-type]');
tools.forEach(t => {
  t.addEventListener('click', () => {
    tools.forEach(x => x.classList.remove('active'));
    t.classList.add('active');
    activeType = t.dataset.type;
  });
});

const muteBtn = document.getElementById('mute-btn');
muteBtn.addEventListener('click', () => {
  isMuted = !isMuted;
  if (masterGain) masterGain.gain.linearRampToValueAtTime(isMuted ? 0 : 0.5, audioCtx.currentTime + 0.1);
  muteBtn.querySelector('span:first-child').textContent = isMuted ? '🔇' : '🔊';
  muteBtn.querySelector('.tooltip').textContent = isMuted ? 'Unmute' : 'Mute All';
});

const clearBtn = document.getElementById('clear-btn');
clearBtn.addEventListener('click', clearAll);

function getPos(e) {
  const rect = canvas.getBoundingClientRect();
  const cx = e.clientX ?? (e.touches && e.touches[0].clientX);
  const cy = e.clientY ?? (e.touches && e.touches[0].clientY);
  return { x: cx - rect.left, y: cy - rect.top };
}

function findObject(x, y) {
  for (let i = objects.length - 1; i >= 0; i--) {
    const o = objects[i];
    const dx = o.x - x, dy = o.y - y;
    if (dx * dx + dy * dy < (o.r + 14) ** 2) return o;
  }
  return null;
}

function updateCursor() {
  canvas.classList.remove('grabbing', 'hovering');
  if (dragging) canvas.classList.add('grabbing');
  else if (hoveredObject) canvas.classList.add('hovering');
}

canvas.addEventListener('mousemove', e => {
  const p = getPos(e);
  mouseX = p.x; mouseY = p.y;

  const prevHover = hoveredObject;
  hoveredObject = findObject(p.x, p.y) || null;

  if (prevHover !== hoveredObject) {
    updateCursor();
    if (hoveredObject) {
      const info = TYPE_INFO[hoveredObject.type];
      hoverLabel.textContent = `${info.label} — ${info.note}`;
      hoverLabel.style.left = (e.clientX + 16) + 'px';
      hoverLabel.style.top = (e.clientY - 10) + 'px';
    }
    hoverLabel.style.opacity = hoveredObject ? 1 : 0;
  }

  if (hoveredObject) {
    hoverLabel.style.left = (e.clientX + 16) + 'px';
    hoverLabel.style.top = (e.clientY - 10) + 'px';
  }
});

canvas.addEventListener('mouseleave', () => {
  hoveredObject = null;
  hoverLabel.style.opacity = 0;
  updateCursor();
});

canvas.addEventListener('mousedown', e => {
  if (!audioCtx) return;
  resumeAudio();
  const p = getPos(e);
  if (e.button === 2) {
    const o = findObject(p.x, p.y);
    if (o) removeObject(o.id);
    return;
  }
  const o = findObject(p.x, p.y);
  if (o) {
    dragging = o;
    o.grabbed = true;
    dragOffX = p.x - o.x;
    dragOffY = p.y - o.y;
    spawnParticles(o.x, o.y, COLORS[o.type], 4);
  } else {
    addObject(activeType, p.x, p.y);
  }
  updateCursor();
});

canvas.addEventListener('mousemove', e => {
  if (!dragging) return;
  const p = getPos(e);
  dragging.x = p.x - dragOffX;
  dragging.y = p.y - dragOffY;
});

canvas.addEventListener('mouseup', () => {
  if (dragging) dragging.grabbed = false;
  dragging = null;
  updateCursor();
});

canvas.addEventListener('mouseleave', () => {
  if (dragging) dragging.grabbed = false;
  dragging = null;
  updateCursor();
});

canvas.addEventListener('contextmenu', e => e.preventDefault());

/* Touch */
canvas.addEventListener('touchstart', e => {
  if (!audioCtx) return;
  resumeAudio();
  e.preventDefault();
  const p = getPos(e);
  const o = findObject(p.x, p.y);
  if (o) {
    dragging = o;
    dragOffX = p.x - o.x;
    dragOffY = p.y - o.y;
  } else {
    addObject(activeType, p.x, p.y);
  }
}, { passive: false });

canvas.addEventListener('touchmove', e => {
  e.preventDefault();
  if (!dragging) return;
  const p = getPos(e);
  dragging.x = p.x - dragOffX;
  dragging.y = p.y - dragOffY;
}, { passive: false });

canvas.addEventListener('touchend', () => { dragging = null; });

/* ---------- Rendering ---------- */

const bgStars = [];
for (let i = 0; i < 100; i++) {
  bgStars.push({
    x: Math.random(), y: Math.random(),
    r: 0.3 + Math.random() * 1.5,
    speed: 0.02 + Math.random() * 0.06,
    phase: Math.random() * Math.PI * 2,
    layer: Math.random() < 0.3 ? 0.5 : 1,
  });
}

function getAmplitude(o) {
  if (!o.sound.analyser) return 0;
  o.sound.analyser.getByteFrequencyData(o.sound.dataArray);
  let sum = 0;
  for (let i = 0; i < o.sound.dataArray.length; i++) sum += o.sound.dataArray[i];
  return sum / (o.sound.dataArray.length * 255);
}

function draw() {
  const now = performance.now();

  // Background trail with darkening
  ctx.fillStyle = 'rgba(10, 10, 15, 0.3)';
  ctx.fillRect(0, 0, W, H);

  // Stars
  for (const s of bgStars) {
    const alpha = 0.1 * s.layer + 0.15 * s.layer * Math.sin(now * 0.001 * s.speed + s.phase);
    ctx.fillStyle = `rgba(200, 210, 255, ${alpha})`;
    ctx.beginPath();
    ctx.arc(s.x * W, s.y * H, s.r * (0.8 + 0.2 * Math.sin(now * 0.0007 + s.phase)), 0, Math.PI * 2);
    ctx.fill();
  }

  // Connection lines between nearby objects
  ctx.lineWidth = 0.8;
  for (let i = 0; i < objects.length; i++) {
    const a = objects[i];
    for (let j = i + 1; j < objects.length; j++) {
      const b = objects[j];
      const dx = a.x - b.x, dy = a.y - b.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      const maxDist = 250;
      if (dist < maxDist) {
        const alpha = (1 - dist / maxDist) * 0.08;
        const col = COLORS[a.type];
        ctx.strokeStyle = `rgba(${col.r}, ${col.g}, ${col.b}, ${alpha})`;
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
        ctx.stroke();
      }
    }
  }

  // Objects
  for (const o of objects) {
    const col = COLORS[o.type];
    const age = Math.min((now - o.birth) / 500, 1);
    o.r += (o.targetR - o.r) * 0.07;

    // Hover lerp
    const targetHover = (o === hoveredObject || o.grabbed) ? 1 : 0;
    o.hover += (targetHover - o.hover) * 0.12;

    // Audio reactivity
    const amp = getAmplitude(o);
    const pulse = 1 + amp * 0.5 + 0.06 * Math.sin(now * 0.002 + o.phase);
    const radius = o.r * pulse * (0.5 + 0.5 * age) * (1 + o.hover * 0.2);

    // Grabbing offset visual
    const offX = o.grabbed ? (mouseX - o.x) * 0.05 : 0;
    const offY = o.grabbed ? (mouseY - o.y) * 0.05 : 0;
    const drawX = o.x + offX;
    const drawY = o.y + offY;

    // Outer glow
    const grad = ctx.createRadialGradient(drawX, drawY, radius * 0.2, drawX, drawY, radius * (4 + o.hover * 2));
    grad.addColorStop(0, `rgba(${col.r}, ${col.g}, ${col.b}, ${(0.2 + amp * 0.15 + o.hover * 0.1) * age})`);
    grad.addColorStop(0.4, `rgba(${col.r}, ${col.g}, ${col.b}, ${(0.06 + amp * 0.04) * age})`);
    grad.addColorStop(1, `rgba(${col.r}, ${col.g}, ${col.b}, 0)`);
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(drawX, drawY, radius * (4 + o.hover * 2), 0, Math.PI * 2);
    ctx.fill();

    // Core circle
    ctx.fillStyle = `rgba(${col.r}, ${col.g}, ${col.b}, ${(0.75 + amp * 0.25 + o.hover * 0.15) * age})`;
    ctx.beginPath();
    ctx.arc(drawX, drawY, radius, 0, Math.PI * 2);
    ctx.fill();

    // Inner highlight
    ctx.fillStyle = `rgba(255, 255, 255, ${(0.15 + amp * 0.15) * age})`;
    ctx.beginPath();
    ctx.arc(drawX - radius * 0.2, drawY - radius * 0.2, radius * 0.35, 0, Math.PI * 2);
    ctx.fill();

    // Interactive ring
    const ringSize = radius * (1.6 + 0.4 * o.hover + 0.3 * amp);
    ctx.strokeStyle = `rgba(${col.r}, ${col.g}, ${col.b}, ${(0.3 + amp * 0.2 + o.hover * 0.25) * age})`;
    ctx.lineWidth = 1.2 + o.hover * 0.8;
    ctx.beginPath();
    ctx.arc(drawX, drawY, ringSize, 0, Math.PI * 2);
    ctx.stroke();

    // Pulsing ring for bell / pulse
    if (o.type === 'bell' || o.type === 'pulse') {
      const pulseRing = radius * (2.5 + 0.8 * Math.sin(now * 0.003 + o.phase));
      ctx.strokeStyle = `rgba(${col.r}, ${col.g}, ${col.b}, ${(0.15 + amp * 0.1) * age})`;
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.arc(drawX, drawY, pulseRing, 0, Math.PI * 2);
      ctx.stroke();
    }

    // Waveform dots around the ring for any type (audio reactive)
    if (amp > 0.05) {
      const dotCount = 8;
      const dotR = 1.5 + amp * 2;
      const orbitR = ringSize + 6 + amp * 8;
      ctx.fillStyle = `rgba(${col.r}, ${col.g}, ${col.b}, ${0.4 + amp * 0.4})`;
      for (let k = 0; k < dotCount; k++) {
        const a = o.phase + (now * 0.0005) + (k / dotCount) * Math.PI * 2;
        ctx.beginPath();
        ctx.arc(drawX + Math.cos(a) * orbitR, drawY + Math.sin(a) * orbitR, dotR, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }

  // Particles
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vx *= 0.97;
    p.vy *= 0.97;
    p.life -= p.decay;
    if (p.life <= 0) {
      particles.splice(i, 1);
      continue;
    }
    ctx.fillStyle = `rgba(${p.color.r}, ${p.color.g}, ${p.color.b}, ${p.life * 0.6})`;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r * p.life, 0, Math.PI * 2);
    ctx.fill();
  }

  // Ambient mouse trail near cursor
  if (!dragging) {
    const trailCol = COLORS[activeType];
    ctx.fillStyle = `rgba(${trailCol.r}, ${trailCol.g}, ${trailCol.b}, 0.03)`;
    ctx.beginPath();
    ctx.arc(mouseX, mouseY, 20 + Math.sin(now * 0.005) * 4, 0, Math.PI * 2);
    ctx.fill();
  }

  // Vignette
  const vig = ctx.createRadialGradient(W/2, H/2, Math.min(W,H)*0.25, W/2, H/2, Math.max(W,H)*0.85);
  vig.addColorStop(0, 'rgba(0,0,0,0)');
  vig.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = vig;
  ctx.fillRect(0, 0, W, H);

  requestAnimationFrame(draw);
}

/* ---------- Start Overlay ---------- */

const overlay = document.getElementById('overlay');
const startBtn = document.getElementById('start-btn');

startBtn.addEventListener('click', (e) => {
  e.stopPropagation();
  initAudio();
  overlay.classList.add('hidden');
  draw();
});

overlay.addEventListener('click', () => {
  initAudio();
  overlay.classList.add('hidden');
  draw();
});
</script>
</body>
</html>
